/**
 * Loads the bundled cores of a test package:
 * `data/bootstrap/index.json`, generated by extension/build/bootstrap.ts, and
 * `data/bootstrap/cores/<sha256>.json`. The shipping package has none: a missing index means no
 * bundled cores, which is not an error.
 *
 * The cores are the package's own data, checked when the package was built. Each load re-hashes
 * each core against its index entry, parses it and checks its identity (verifyCoreBytes); it does
 * not validate the core again. A core that fails a check is skipped; the others still load.
 */

import {profileByApp} from '@intactwarden/profiles';
import type {AppId, Assurance, BootstrapIndex, VariantId} from '../contracts.ts';
import {BOOTSTRAP_INDEX_PATH, buildIdOf} from '../contracts.ts';
import {
  APPS,
  isRecord,
  isSafeCount,
  isSha256,
  VARIANTS,
  VERSION_XYZ,
  type TrustLog,
  noLog,
} from './common.ts';
import {verifyCoreBytes, type ParsedCore} from './coresDb.ts';

export const BOOTSTRAP_SCHEMA = 'intactwarden.bootstrap/1';
export const MAX_INDEX_BYTES = 1024 * 1024;
const MAX_CORES = 64;

export type BootstrapCoreEntry = BootstrapIndex['cores'][number];

export interface BootstrapCore {
  readonly entry: BootstrapCoreEntry;
  readonly parsed: ParsedCore;
}

export interface BootstrapResult {
  readonly cores: readonly BootstrapCore[];
  readonly skipped: readonly {readonly path: string; readonly reason: string}[];
  /** Index-level failure (no cores load), or null (also when the package has no index). */
  readonly error: string | null;
}

/** Reads one package file; null when it does not exist. */
export type PackageReader = (path: string) => Promise<Uint8Array | null>;

/** The assurance class the bundled profile gives a variant, or null for an unknown pair. */
export function profileAssurance(app: AppId, variant: VariantId): Assurance | null {
  const profile = profileByApp(app);
  const v = profile?.variants[variant];
  return v === undefined ? null : v.assurance;
}

function validateEntry(raw: unknown): BootstrapCoreEntry | string {
  if (!isRecord(raw)) return 'entry';
  const {app, variant, version, build_id, assurance, sha256, size, path} = raw;
  if (typeof app !== 'string' || !(APPS as readonly string[]).includes(app)) return 'app';
  if (typeof variant !== 'string' || !(VARIANTS as readonly string[]).includes(variant)) {
    return 'variant';
  }
  if (typeof version !== 'string' || !VERSION_XYZ.test(version)) return 'version';
  const key = {app: app as AppId, variant: variant as VariantId, version};
  if (build_id !== buildIdOf(key)) return 'build-id';
  const expectedAssurance = profileAssurance(key.app, key.variant);
  if (expectedAssurance === null || assurance !== expectedAssurance) return 'assurance';
  if (!isSha256(sha256)) return 'sha256';
  if (!isSafeCount(size) || size === 0) return 'size';
  if (path !== `data/bootstrap/cores/${sha256}.json`) return 'path';
  return {...key, build_id, assurance: expectedAssurance, sha256, size, path};
}

/** Loads and verifies the bundled bootstrap, if the package has one. Never throws. */
export async function loadBootstrap(
  read: PackageReader,
  log: TrustLog = noLog,
): Promise<BootstrapResult> {
  const fail = (error: string): BootstrapResult => {
    log('trust.bootstrap.failed', {error});
    return {cores: [], skipped: [], error};
  };
  let bytes: Uint8Array | null;
  try {
    bytes = await read(BOOTSTRAP_INDEX_PATH);
  } catch {
    bytes = null;
  }
  if (bytes === null) return {cores: [], skipped: [], error: null};
  if (bytes.length > MAX_INDEX_BYTES) return fail('index-too-large');
  let raw: unknown;
  try {
    raw = JSON.parse(new TextDecoder('utf-8', {fatal: true}).decode(bytes));
  } catch {
    return fail('index-json');
  }
  if (!isRecord(raw) || raw['schema'] !== BOOTSTRAP_SCHEMA) return fail('index-schema');
  if (!Array.isArray(raw['cores']) || raw['cores'].length > MAX_CORES) return fail('index-cores');

  const cores: BootstrapCore[] = [];
  const skipped: {path: string; reason: string}[] = [];
  const seen = new Set<string>();
  for (const [i, item] of (raw['cores'] as unknown[]).entries()) {
    const entry = validateEntry(item);
    if (typeof entry === 'string') {
      skipped.push({path: `cores[${i}]`, reason: entry});
      continue;
    }
    if (seen.has(entry.build_id)) {
      skipped.push({path: entry.path, reason: 'duplicate'});
      continue;
    }
    let coreBytes: Uint8Array | null;
    try {
      coreBytes = await read(entry.path);
    } catch {
      coreBytes = null;
    }
    if (coreBytes === null) {
      skipped.push({path: entry.path, reason: 'missing'});
      continue;
    }
    const check = await verifyCoreBytes(coreBytes, {
      sha256: entry.sha256,
      size: entry.size,
      app: entry.app,
      variant: entry.variant,
      version: entry.version,
    });
    if (!check.ok) {
      skipped.push({path: entry.path, reason: check.reason});
      continue;
    }
    seen.add(entry.build_id);
    cores.push({entry, parsed: check.parsed});
  }
  for (const s of skipped) log('trust.bootstrap.skipped', s);
  return {cores, skipped, error: null};
}
